    "description": "West Knoxville bar-and-grill that knows exactly what it is: a place to watch games, eat better-than-necessary food, and sit by the outdoor fireplace when the weather cooperates. The menu comes from local chefs who understand that bar food doesn't mean lazy food—hot honey chicken sandwich with proper heat and sweet, hickory-smoked prime rib that tastes like someone cared, wood-fired pizza that holds its own. Twenty-two beers on tap, ninety-one whiskeys behind the bar, craft cocktails if you want them. Two patios, dog-friendly, enough TVs to catch every game without feeling like a sports bar cliché. The hot honey shows up on multiple dishes because they figured out how to do it right. Farragut locals treat it like their spot; Turkey Creek shoppers use it as a landing pad.",
    "atmosphere": "Indoor-outdoor setup with amphitheater-style courtyard seating around a wood-burning fireplace. Round signature bar anchors three dining bays. Hometown-relaxed energy—TVs on, conversation still possible. Patio fills up when it's nice out. The vibe is \"meet here after work\" not \"special occasion,\" which is the whole point.",
