    "description": "Chef Matt Petro turned a 1930s Baptist church into a brunch-forward casual spot that works as both a trailhead refuel station and an elevated-casual dinner option. The 71 Smash Burger is the move—simple, well-executed, properly smashed with crispy edges. Brunch runs all day until 3 PM with churro French toast and breakfast burritos that mountain bikers actually want after a ride. The Tuscan chicken and Portobello Philly prove Petro knows how to do comfort food with enough refinement to justify the setting without losing the plot. Full bar with local drafts and craft cocktails (Baker Creek Bellini is the house drink). This isn't fine dining—it's the kind of place where you can show up sweaty from the trails or dressed for a casual date and both feel right.",
