    "description": "Brian Strutz spent a year in Italy learning the craft, then came back to Knoxville and opened this 40-seat wood-fired pizzeria in 2016. The naturally-leavened sourdough starter he keeps alive produces crusts with that perfect puff and char—light, chewy, properly blistered from the custom wood-fired oven. USA Today named it to their 2025 Restaurants of the Year list as the sole pizzeria among 44 restaurants nationwide. Food & Wine and Bon Appétit noticed early.\n\nEight pizzas on the menu—four red sauce, four white—with real balance and restraint. The truffle pie (aged mozzarella, white truffle oil, speck, mushrooms, chives, fig jam) shows what happens when someone understands ingredients instead of just piling them on. Staff pulls fresh mozzarella daily from curds. House-made gelato uses local milk and cream, including espresso gelato made with beans from Remedy Coffee next door. Italian wines on tap. Dinner only, reservations through Resy recommended weeks ahead.",
    "atmosphere": "Forty seats split between communal tables and individual seating, marble dough station visible, concrete countertops, custom white oak tables from Fork Design. Candlelit at night. The kind of intimate space where you can watch the whole operation—pizza making, dough stretching, oven tending. Paint splatters preserved on original floors acknowledge the building's creative history in downtown Knoxville.",
    "special_features": "USA Today 2025 Restaurant of the Year (sole pizzeria on list). Owner Brian Strutz is Blackberry Farm alumnus who lived in Italy for a year. Uses naturally leavened sourdough starter kept alive for years. Staff pulls fresh mozzarella daily from curds. Featured in Food & Wine and Bon Appétit. Dinner-only service. Signature truffle pie features 15-inch naturally leavened pizza topped with aged mozzarella, white truffle oil, speck ham, mushrooms, chives and finished with fig jam. House-made gelato in small batches. Online ordering available through Toast.",
