    "description": "Neighborhood brewpub in a converted 1950s auto garage where Jesse Bowers brews ten taps on-site and runs the kitchen—opened 2017, pioneering Bearden's craft beer scene before the Cedar Bluff expansion. The philosophy is \"creating the Abridged version\": low-gravity beers with outsized flavor like Boysenberry Gose and Breakfast Stout loaded with coffee, vanilla, cinnamon, and chocolate. Food's pub classics with Southern leanings—the Abridged Burger (ground brisket, bacon, fried Brussels sprout petals, house aioli) and Pot Roast Nachos are what regulars order. Fast-casual setup (order at the bar), dog-friendly patio with heaters, families everywhere, gets packed Friday-Saturday (show up by 5 PM or plan on waiting). This isn't a date spot unless you're cool with industrial garages and kids running around, but for neighborhood hangs over solid beer and better-than-it-needs-to-be pub food, it delivers.",
    "atmosphere": "Converted auto garage with visible brewing tanks, industrial bones, fast-casual ordering (bar only, no table service), large dog-friendly patio with heat lamps. Mix of families, craft beer regulars, neighborhood crews. Bustling and loud when packed (which is often), relaxed on off-peak hours. Zero pretense.",
