    "description": "Family-run Mexican spot that succeeds at being exactly what South Knoxville needs: authentic recipes from Acapulco executed with care, fast service that doesn't sacrifice quality, and a salsa bar that regulars call \"stratospheric.\" The chicken cheese and rice hits the comfort food sweet spot, nachos fajita come loaded properly, and carne asada fries deliver on the promise of crispy-bottomed, cheese-melted excess. Margarita Mondays mean $2.99 house margaritas—the kind of pricing that builds loyalty. It's not trying to reinvent Mexican food; it's trying to do it right, with real recipes and a family behind them. Lunch specials like the burrito Mexicano at $8.99 make it easy to become a regular.",
    "atmosphere": "Bright, family-friendly dining room with festive Mexican decor and a patio. The kind of place where service moves quickly but doesn't feel rushed. Families, couples, solo diners grabbing lunch. Salsa bar creates a DIY energy. Casual enough for weeknight dinner, festive enough for celebration.",
