    "hours": "{\"mon\": \"closed\", \"tue\": \"closed\", \"wed\": \"4pm-10pm\", \"thu\": \"4pm-10pm\", \"fri\": \"4pm-11pm\", \"sat\": \"4pm-11pm\", \"sun\": \"12pm-9pm\"}",
    "description": "Food truck turned brick-and-mortar success story that proves the transition can work when you stay true to what made people line up in the first place. Chef David and daughters Allie and Rachel have been slinging bold-flavored comfort food since 2016, opened this Fourth and Gill spot in 2021, and kept the cult favorites while adding gastropub ambitions. The bourbon meatloaf is the move—scratch-made, grilled in Italian cream butter, topped with maple bourbon BBQ, bacon crumbles, and crispy onion strings. Black brew pulled pork with maple bourbon BBQ delivers depth you don't expect from pulled pork. Hot honey chicken fingers, Brussels sprouts with fig dip, and brisket rolls round out the hits. Live music Wednesday-Sunday (blues, rock, local acts), Sunday comedy shows at 7:30 PM (free, 18+), Tuesday trivia. Coffee bar opens mornings, full bar with craft cocktails takes over evenings. Reservations via Resy, which you should use because the intimate dining room fills up fast.",
    "atmosphere": "Rustic gastropub vibe that doesn't try too hard—exposed brick, live music stage, beer garden out back (dogs welcome). Wednesday-Sunday nights bring blues and rock acts; Sundays shift to comedy. The crowd skews local regulars who remember the food truck days mixed with Fourth and Gill neighbors and Old City spillover. Energy picks up with the music but never gets aggressively loud. Coffee bar mornings feel neighborhood café; evenings lean music venue with a full bar. Outdoor space gets packed when weather cooperates.",
    "special_features": "Live music Wednesday-Saturday nights; Laugh Alive Comedy Show every Sunday 7:30 PM (free, 18+); Tuesday trivia nights; Weekend brunch Saturday-Sunday mornings; Coffee bar; Craft cocktails and craft beer; Pet-friendly; Reservations via Resy; Historic Fourth and Gill neighborhood location",
