    "description": "West Knoxville Italian from 1988 running on recipes Geraldine Ida Altruda brought from Italy in 1937, when she immigrated at age 12. Paul (her son, the owner) grew up stirring pots in her kitchen—those same secret recipes are what you're eating now, 36 years into this operation. The garlic rolls are famous for a reason: made fresh daily, served warm with every meal, the kind of thing regulars think about before they even arrive. Fettuccine alfredo with spinach is the move—cream sauce that coats the pasta properly, generous enough for two meals. Eggplant Nicole layers breaded eggplant with ricotta and marinara. Shrimp Altruda, veal marsala, chicken parmigiana all executed with portion sizes that assume you're taking home leftovers. The salad with house dressing starts every meal. This isn't trying to be modern Italian or gastropub Italian—it's American red-sauce Italian done the way families have been doing it for decades, and it works.",
    "atmosphere": "Cozy booths that feel semi-private, soft lighting, minimal noise because the dining room is broken into smaller sections. The vibe is 'Sunday dinner at an Italian grandmother's house'—warm, unpretentious, designed for families and couples who want to talk without shouting. Not trendy, not trying to be. Just comfortable.",
