    "description": "Fourth-generation Italian restaurant where Chef Tiffany—who trained in Tuscan and French kitchens from Biltmore to Bravo, cooked for celebrities and athletes—brings proper regional technique to a tiny Kingston Pike storefront. The family lineage traces to 1936 Boston, and you can taste the generations in dishes like pan-roasted fish with lemon-caper butter and housemade pastas. This isn't red-sauce nostalgia—it's precise, classically trained cooking that respects the source material. Very small space (no high chairs, no strollers, no kids menu) means date night or nothing. Gets loud around 6:15 PM when happy hour peaks, settles into intimate territory by 7 PM.",
    "atmosphere": "Warmly lit dining room that seats maybe forty people. European café vibe meets New England family restaurant—white tablecloths, attentive service, the kind of place where the owner works the room. Lively when full, conversation-friendly once the initial rush clears.",
