    "description": "Bearden's backyard beer hang where the point is the beer garden, not the retail. Twenty rotating taps of hard-to-find craft—the kind of selection that makes beer nerds drive across town—plus full food menu from The Local Curbside, not just chips. The setup matters: covered pavilion with massive fire pit, ping pong, cornhole, giant Jenga. Dogs allowed, open 365 days, heated in winter. Not trying to be a restaurant with a beer list or a bottle shop with a patio—it's a proper beer garden that happens to sell bottles to go. The vibe is backyard hang, not craft beer church.",
    "atmosphere": "Covered pavilion with open sides, huge central fire pit, picnic tables. Mix of regulars with their dogs, beer geeks checking the tap list, families playing yard games. Casual volume—conversation easy even when crowded. Feels like a well-curated neighborhood backyard where everyone's invited.",
    "special_features": "Open 365 days/year, 20 rotating taps, largest hard-to-find beer selection in Knoxville, heated pavilion, fire pit, yard games (cornhole, ping pong, giant Jenga), dog-friendly, full food menu, bottles/kegs to-go",
