    "website": "https://bhfh.smithbars.com/",
    "hours": "{\"monday\": \"11:00-03:00\", \"tuesday\": \"11:00-03:00\", \"wednesday\": \"11:00-03:00\", \"thursday\": \"11:00-03:00\", \"friday\": \"11:00-03:00\", \"saturday\": \"11:00-03:00\", \"sunday\": \"11:00-03:00\"}",
    "description": "Sports bar that knows exactly what it is: 28 TVs showing every game, 100+ beers, fresh-never-frozen wings in legitimately good sauces (the lemon pepper earns its reputation), and indoor smoking still allowed. Part of the Smith Bars group, which means consistent execution on bar food fundamentals—the Bearden Hill cheesesteak wrap hits, beer-battered cheese curds are properly crispy, fried okra is better than it needs to be. Seven Golden Tee machines, two patios, 3 AM close time. This isn't trying to be elevated pub food or craft cocktail culture—it's a straightforward sports bar for people who want to watch games, drink beer, and not worry about whether their shirt has a collar. The smoking policy and late hours mean it attracts a specific crowd that wants those exact features.",
    "atmosphere": "Twenty-eight screens dominating sightlines, Golden Tee machines in steady use, buzz of conversation punctuated by game reactions. Smoking allowed inside means the air has that familiar bar haze. Crowd skews to regulars who know exactly what they're getting: late-night poker tournaments (free Texas Hold'em Tuesday and Wednesday), cold beer, and zero pretense. Parking situation is tight—lower lot or risk a tow.",
    "special_features": "Indoor smoking allowed, 28 TVs with all sports packages, 100+ beers, 7 Golden Tee machines, 2 patios, free poker tournaments, 3 AM close",
