    "hours": "{\"monday\": \"17:00-21:00\", \"tuesday\": \"17:00-21:00\", \"wednesday\": \"17:00-21:00\", \"thursday\": \"17:00-21:00\", \"friday\": \"17:00-22:00\", \"saturday\": \"17:00-22:00\", \"sunday\": \"Closed\"}",
    "description": "Bearden fine dining spot run by Executive Chef John Bryant, who brings proper technique without the stuffiness. The menu changes seasonally but always leans on East Tennessee farms—Benton's bacon, Cruze Farm dairy, Appalachian rye sourdough—prepared with precision and served in a wood-and-brick space that feels more approachable than white-tablecloth formal. Wine Spectator Award of Excellence winner with a deep list. They've been doing this since 1999, which in restaurant years means they figured out the formula and stopped trying to reinvent it. Reservations recommended, especially weekends.",
    "atmosphere": "Wood and brick interior with an open glass-walled kitchen. More upscale-casual than stuffy fine dining—you'll see jeans-and-blazers next to cocktail dresses. Good table spacing keeps noise manageable. Patio seating available. The vibe is \"special occasion that doesn't require performance.\"",
    "special_features": "Wine Spectator Award of Excellence, glass-walled kitchen, seasonal sourcing from East Tennessee farms, extensive wine list, private lot parking, OpenTable reservations",
