    "website": null,
    "hours": "{\"monday\": \"15:00-21:00\", \"tuesday\": \"15:00-21:00\", \"wednesday\": \"15:00-21:00\", \"thursday\": \"15:00-21:00\", \"friday\": \"12:00-22:00\", \"saturday\": \"11:00-22:00\", \"sunday\": \"11:00-22:00\"}",
    "description": "Happy Holler brewery that took over the Elst Brewing space in August 2024 and kept what worked—head brewer Dan Leonard stayed on, a few crowd favorites from the old lineup remain (Vanilla Milkshake Ale with tweaked recipes), and the neighborhood regulars kept showing up. The beer program leans experimental: 19 taps rotating through Citra Fog NE-IPAs, Centennial IPAs, and oddities like \"Goats-n-Hoes\" that suggest they're having fun back there. Food comes from the Chivo trailer out back while a permanent restaurant gets built inside—tacos, queso, salsa, the usual suspects done well enough that nobody minds eating outside. The vibe is distinctly North Knoxville: Bob Ross painting sessions, vinyl listening area, fire pit for when it's cold, sports on multiple screens, live music weekly. Not trying to be Fourth & Gill fancy, not settling for strip-mall suburban. Knows exactly what a neighborhood brewery should be.",
    "atmosphere": "Spacious industrial brewery space with outdoor seating around a fire pit. Mix of beer nerds, Happy Holler locals, and dog people (they host rescue adoption events). Multiple TVs for sports, vinyl corner for music heads, room to breathe. Friendly bartenders who know their taps. The kind of place where Bob Ross painting nights make perfect sense.",
