    "website": "https://jigandreel.com/",
    "hours": "{\"monday\": \"Closed\", \"tuesday\": \"11:30-00:00\", \"wednesday\": \"11:30-00:00\", \"thursday\": \"11:30-00:00\", \"friday\": \"11:30-01:00\", \"saturday\": \"11:30-01:00\", \"sunday\": \"14:00-21:00\"}",
    "description": "Scottish session pub in Old City that takes the music-first pub concept seriously—live Celtic, Irish, Scottish, and Old Time sessions six nights a week, with instruments hanging on walls for anyone to grab and join. The food program delivers proper Scottish pub fare: haggis with neeps and tatties, steak and ale pie, fish and chips fried in beef tallow, sticky toffee pudding that's actually sticky. The whiskey collection is the real draw: 1,000+ bottles including the Southeast's largest single malt selection (200+ options). Not attempting fine dining or gastropub elevation—this is what Scottish pubs actually are. Music happens nightly, the crowd knows the songs, and the vibe is participatory, not performative. Old City location since 2011.",
    "atmosphere": "Historic Old City building with instruments on walls, dark wood interiors, and the hum of live traditional music most nights. Mix of whiskey enthusiasts, musicians with cases, couples on date nights, and regulars who know every verse. Conversation-friendly early, louder when sessions start. The kind of place where strangers harmonize.",
    "special_features": "Southeast's largest single malt scotch selection (200+), 1,000+ total whiskeys, live music 6 nights/week (Celtic, Irish, Scottish, Old Time sessions), instruments on walls for open participation, historic Old City building, late hours (1 AM Fri-Sat)",
