    "description": "Downtown taqueria that knows exactly what it's doing: inventive tacos that actually work, award-winning margaritas (five years running), and one of the Southeast's deepest tequila collections. The Clusterduck taco—roasted duck, black cherry reduction, goat cheese—sounds like chef-y overthinking but hits. Street corn with roasted jalapeño queso, brisket burritos the size of your forearm, wings that have no business being this good at a taco spot. No reservations, no apologies. The bar program is the real draw: flights of tequila and mezcal, specialty margaritas that justify the hype, plus an unexpected whiskey selection. Gay Street location means walk-friendly to Market Square or Old City. The kind of place that could coast on \"fun downtown spot\" energy but doesn't—ingredients are dialed in, execution is consistent, and the kitchen clearly gives a damn.",
    "atmosphere": "Lively downtown energy with Mexican-American cultural nods throughout. Well-stocked tequila bar dominates the front, funky details everywhere, back area gets tight on weekends. Young professional crowd mixing with tourists, noise level rises with the margarita count. Walk-in only creates a bar-scene vibe even at dinner.",
