    "phone": "(865) 966-0933",
    "website": "https://www.connorsrestaurant.com",
    "hours": "{\"monday\": \"11:00-22:00\", \"tuesday\": \"11:00-22:00\", \"wednesday\": \"11:00-22:00\", \"thursday\": \"11:00-22:00\", \"friday\": \"11:00-23:00\", \"saturday\": \"11:00-23:00\", \"sunday\": \"11:00-22:00\"}",
    "description": "AAA Three Diamond steakhouse that made Yelp's 2024 Top 25 Steakhouses in America. The signature move is the Montague ovens—1800-degree infrared searing with hickory mesquite, locking in juices and creating char that gas grills can't touch. The lobster-crab bisque is thick with actual lobster and crab (not just essence), finished with sherry. Kurobuta pork belly braised in sweet tea shows they're thinking beyond standard steakhouse moves. Chilean sea bass Oscar comes properly executed: asparagus, lump crab, hollandaise that doesn't break. This is corporate-done-right: consistent execution, wine list that works, service trained to read the room.",
    "atmosphere": "Rich wood paneling, working fireplaces, business-casual dress code that bends toward jeans-and-collared-shirt in practice. Turkey Creek location means shopping center parking and suburban clientele. Bar gets busy during happy hour (half-off drinks 3-7 PM daily). White tablecloths without stuffiness.",
    "special_features": "Montague 1800-degree ovens, Happy hour 3-7 PM daily (half-off drafts, well spirits, house wines), OpenTable reservations, Private dining available",
