    "description": "Knoxville institution since 1977 doing what it set out to do: prime grade beef from their own USDA-inspected butcher shop, seafood flown in daily, everything made in-house from the bread to the signature sauces. This is the West location—opened two years after the original Cumberland Avenue spot that closed in 2023 after nearly 50 years. The formula hasn't changed: simple preparations, quality ingredients, Old English hunt club atmosphere that's more comfortable than stuffy. Prime rib is the move here—cooked right, well-seasoned, served with Neva's potatoes (whatever those are, locals swear by them). The Sunday brunch (10am-2pm) is legitimately award-winning with prime rib carving station, made-to-order omelets, and all the sides. Not trying to reinvent steakhouse dining. Just executing the classics with ingredients good enough that simplicity works.",
    "atmosphere": "Old English hunt club aesthetic—exposed brick, wood paneling, vintage touches without going full theme park. Booth seating provides actual privacy even when the dining room is full. Never overly loud despite crowds. The vibe skews special occasion: anniversaries, birthdays, families celebrating something. Professional but not stuffy service. Comfortable enough for regulars, nice enough for impressing out-of-town guests.",
    "special_features": "Private dining room for up to 40 guests, shares space with Cappuccino's Italian restaurant, part of Copper Cellar Family of Restaurants (19+ locations), catering services available, wheelchair accessible, award-winning hospitality since 1975",
