    "description": "Old City's Western-themed nightlife spot where \"Santa Fe meets Southbound\"—think margaritas in mason jars, cowboy hats over UT jerseys, and a crowd that showed up to party, not to two-step. This is Leigh Burch III's formula applied to honky-tonk aesthetics: pack the place Friday-Saturday nights, crank the music, move drinks fast. Live music on weekends (9 PM-midnight), sports on the TVs, daily drink specials engineered for volume ($5 Lone Star buckets, $10 NUTRL buckets, $5 house margs on Thursdays). The Western theme is branding, not culture—more Instagram backdrop than authentic roadhouse. But if you're 25, it's your friend's birthday, and you want somewhere loud in Old City that isn't a sports bar, it does the job. The specials are aggressive, the music is loud, and nobody's pretending this is anything but a good time.",
    "atmosphere": "High-energy nightlife bar with Western decor as set dressing. Young crowd (mostly 20s-early 30s), loud music, drink-special-driven vibe. Think birthday parties, bachelorettes, and UT game days—not actual cowboys.",
