    "hours": "Mon: Closed, Tue-Thu: 4:30pm-9pm, Fri-Sat: 4:30pm-10pm, Sun: 4:30pm-9pm",
    "description": "Farragut Crossing restaurant where Executive Chef Aaron Ward (15 single-concept restaurants under his belt) runs a seasonally rotating menu that actually rotates—think beef tenderloin in puff pastry with mushroom duxelles, short ribs over gnocchi, pappardelle bolognese that reviewers call \"perfectly yummy.\" The tapas-style small plates approach means you can taste across the menu without committing to one thing. Opened April 2023 in a Turkey Creek shopping center location that works better than it should—warm lighting, casual atmosphere that reads date-night-capable without being stuffy. Cocktail program exists but isn't the draw. The food is the point, and it changes with seasons and chef creativity. Reviewers consistently mention the salmon (\"best in Knoxville\") and presentation quality. Some grumble about portions versus price ($160 for two people with apps and drinks), but the quality is there. This is what upscale casual actually means in Farragut—comfortable enough for regulars, polished enough for occasions.",
    "atmosphere": "Shopping center restaurant that doesn't feel like a shopping center restaurant. Warm lighting, comfortable seating, noise level that allows conversation. Mix of date-night couples and family celebrations. The kind of place where you can dress up or not, and either works. No pretense, just solid execution on atmosphere fundamentals.",
    "special_features": "Seasonally rotating menu, Chef Aaron Ward, tapas-style small plates, craft cocktails",
    "opening_date": "2023-04-12T00:00:00Z",
    "area": "Turkey Creek",
