    "website": "https://fioribar.com",
    "hours": "{\"monday\": \"Closed\", \"tuesday\": \"5:00 PM - 10:00 PM\", \"wednesday\": \"5:00 PM - 10:00 PM\", \"thursday\": \"5:00 PM - 10:00 PM\", \"friday\": \"4:00 PM - 12:00 AM\", \"saturday\": \"4:00 PM - 12:00 AM\", \"sunday\": \"Closed\"}",
    "description": "Jesse and Corey Vose opened Fiori in 2024 in the Old City spot that used to be Vid'l, and they're executing a specific vision: upscale Italian-American lounge that takes itself seriously where it matters (the food, the drinks) and doesn't where it shouldn't (the vibe). The name means \"flower\" in Italian, which explains the two decorative cherry blossom trees and pink neon—could read gimmicky, but the kitchen backs it up. R.H.C. Lobster Roll is named for Jesse's great-grandfather, a Maine lobster fisherman, made with knuckle, claw, and tail meat on a proper roll. Lobster Alla Vodka does the vodka cream sauce right. Everything's made from scratch, which means something here—Cornish hen, cavatappi Bolognese, house focaccia. Happy hour runs 4-6 PM Friday-Saturday, 5-6 PM Tuesday-Thursday. Reservations recommended via Tock. Closed Sunday-Monday, which is either confident or limiting depending on how you see it.",
    "atmosphere": "Dark, moody lounge with plush booth seating under those cherry blossom trees and pink neon that somehow works instead of feeling like a nightclub. Dim lighting designed for dates and conversations you don't want overheard. The \"sexy\" descriptor in their marketing is accurate without being embarrassing about it—grown-up intimate, not trying-too-hard sultry. Cocktail-forward crowd, anniversary dinners, people who want to feel fancy without a suit-and-tie requirement. Service quality seems inconsistent based on reviews (one person raved about \"impeccable\" service, another hit disorganized and inattentive twice in two weeks). When it's on, it's the upscale Italian lounge Knoxville didn't know it needed. When it's off, you're paying $$$ prices for uneven execution.",
    "special_features": "Happy hour 4-6 PM Fri-Sat, 5-6 PM Tue-Thu. Reservations via Tock. Signature R.H.C. Lobster Roll (Maine lobster). Handcrafted cocktails (Violet Whisper with Empress gin). Everything made from scratch. Decorative cherry blossom trees. Pink neon lighting. Closed Sun-Mon.",
    "opening_date": "2024-05-01T00:00:00Z",
    "area": "Old City",
