    "hours": "{\"monday\": \"4:00 PM - 11:00 PM\", \"tuesday\": \"4:00 PM - 11:00 PM\", \"wednesday\": \"4:00 PM - 11:00 PM\", \"thursday\": \"4:00 PM - 11:00 PM\", \"friday\": \"4:00 PM - 12:00 AM\", \"saturday\": \"4:00 PM - 12:00 AM\", \"sunday\": \"2:00 PM - 8:00 PM\"}",
    "description": "Rooftop lounge on the 10th floor of a downtown hotel—literally one of the only places in Knoxville where you can drink 10 stories above street level while looking at the Smokies. The views are the whole point: floor-to-ceiling glass wraps the indoor bar, outdoor terrace has fire pits and seating that faces west toward the mountains. Not trying to be a nightclub or a dive—this is specifically for people who want craft cocktails ($14 average), elevated bar snacks (pimento cheese with house jam, truffle boursin), and a sophisticated atmosphere without club music or TVs. The whiskey program is serious: rare pours ranging $23-$225, one of the best bourbon selections in town. Service skews knowledgeable and accommodating—bartenders mix custom drinks based on what you actually like. Works as a pre-dinner cocktail spot, post-work unwind with a view, or special occasion destination. The outdoor space is seasonal, so timing matters.",
    "atmosphere": "Hotel rooftop with floor-to-ceiling windows and panoramic mountain views. Indoor space feels polished—modern furnishings, ambient lighting, sophisticated without being stuffy. Outdoor terrace centers around fire pits with lounge seating facing the skyline. Crowd skews dressed-up professionals, tourists celebrating something, locals treating it as an occasion. Conversation-level noise, no DJ, live music on select nights. The vibe says \"this is worth $14 cocktails\" without being pretentious about it.",
    "special_features": "rooftop venue, 10th floor views, Smoky Mountain panoramas, floor-to-ceiling windows, fire-pit seating, rare whiskey collection ($23-$225 pours), seasonal outdoor terrace, live music select nights, Resy reservations accepted",
