    "description": "Neighborhood taproom where the brewer moved from Colorado specifically to do this, the chef came from Clinch River, and the owners live six minutes away. Brandon Smith keeps ten house beers rotating—Pond Gap Pale with New Zealand hops, a German Bock aged on French oak, porter with Puerto Rican cocoa nibs. Wines fermented on-site, naturals on tap, zero pretension. The smash burger on Flourhead buns is reliable; the vegan flatbread with house kimchi and ginger chimichurri shows what the kitchen can actually do. Gochujang wings have real heat. Elderberry kombucha is the sleeper.",
    "atmosphere": "Former Albright Grove space, warmer now. Brewing operation visible behind the bar. Shelton Walsmith paintings on exposed brick. Communal tables in the center, two-tops along walls. Greenway cyclists, young families before sunset, neighbors who remember Golden Roast. Conversation-friendly volume. Monday-Tuesday: taproom only with shareables fridge for book clubs.",
    "special_features": "All beer brewed on-site; wines fermented on-site and served on tap; natural wines from small producers; 10 rotating house beers; Friday live music (jazz/Americana) curated by Jessica Watson; Monday-Tuesday shareables fridge; Shelton Walsmith rotating art shows; chef Brandon Cruze (Clinch River alum); Flourhead Bakery buns; house kimchi; elderberry kombucha with ginger, cinnamon, allspice",
