    "website": "https://harvestknox.com/",
    "hours": "{\"monday\": \"11:00-21:00\", \"tuesday\": \"11:00-21:00\", \"wednesday\": \"11:00-21:00\", \"thursday\": \"11:00-21:00\", \"friday\": \"11:00-22:00\", \"saturday\": \"10:00-22:00\", \"sunday\": \"10:00-21:00\"}",
    "description": "Upscale-casual Bearden spot that knows exactly what it's doing: aged Midwestern steaks, fresh daily seafood, house-made pastas, and a seasonal menu that shifts with what's available. Head Chef Matthew Glickman runs a kitchen that sources thoughtfully (Benton's bacon, hand-cut steaks) without making a production of it. The menu changes regularly—beef carpaccio one week, a fish special the next—which means locals come back to see what's on. Weekend brunch adds another reason to show up. This is the less expensive sibling to the downtown location, meaning you can do a proper dinner without hitting $250. For date nights or celebratory meals where you want the food to be the point, not the scene.",
    "atmosphere": "Upscale without being stuffy. Dim lighting, earthy tones, conversation-friendly volume. The crowd skews date night and special occasions but doesn't feel precious about it. Bearden location at Kingston Pike and Mohican, across from Nama Sushi Bar.",
