    "website": null,
    "hours": "{\"note\": \"Call for current hours\"}",
    "description": "South Knoxville neighborhood tavern where pool sharks, karaoke enthusiasts, and locals who want a no-frills night out congregate on Maryville Pike. The draw is straightforward: pool tables, bar games, cheap drinks, and classic American bar food (think tacos, wings, the basics). Live music some nights, karaoke others—the kind of place that adapts to whatever the crowd wants. Not trying to be craft cocktail central or gastropub-adjacent. Just a functional tavern where the beer is cold, the pool cues are racked, and nobody's checking your outfit. The 4.7 Google rating suggests they've figured out their lane and stay in it.",
    "atmosphere": "Neighborhood bar energy with pool tables as the centerpiece. Mix of regulars who know the bartender by name and newcomers looking for casual games. Described as \"spectacular atmosphere\" by locals, which translates to: unpretentious, welcoming, no performance required. Bar games, music, conversation-friendly volume when it's not karaoke night.",
