    "website": "https://www.jcholdway.com",
    "hours": "{\"tuesday\": \"17:00-21:00\", \"wednesday\": \"17:00-21:00\", \"thursday\": \"17:00-21:00\", \"friday\": \"17:00-21:45\", \"saturday\": \"17:00-21:45\", \"sunday\": \"closed\", \"monday\": \"closed\"}",
    "description": "James Beard Award-winning chef Joseph Lenn's wood-fired love letter to Appalachian cooking, named after his late uncle. This is what happens when a chef who trained at Blackberry Farm and won Best Chef Southeast brings museum-level technique to Southeast ingredients. The wood-fire isn't a gimmick—it's the entire point, a nod to cooking before electricity hit rural Appalachia. Menu changes daily based on what's available, but expect things like slow-cooked farm eggs, two-day salt-brined roasted chicken with crackling skin, and pasta that shows up in The New York Times' 50 Best Restaurants list. Michelin Guide recognized, Garden & Gun approved. This is special-occasion dining that earns it.",
    "atmosphere": "Historic 1927 Daylight Building with exposed brick and wood-fire glow. Sophisticated but not stiff—you're here for a celebration, and the room knows it. Well-dressed couples, anniversary dinners, proposals. Conversation-friendly volume with open kitchen energy.",
    "special_features": "Chef's Tasting Menu ($175), Center of Table family-style ($99pp), open kitchen with wood-fire hearth, Resy reservations required, wine pairings available ($99+)",
