    "website": "https://joeyssandwichshop.com/",
    "hours": "{\"monday\": \"07:00-14:30\", \"tuesday\": \"07:00-14:30\", \"wednesday\": \"07:00-14:30\", \"thursday\": \"07:00-14:30\", \"friday\": \"07:00-14:30\", \"saturday\": \"07:00-14:00\", \"sunday\": \"closed\"}",
    "description": "Farragut sandwich shop where Joey Natour landed after his parents sold Pete's Restaurant—the downtown breakfast spot they ran for 38 years. He kept the family playbook: quality ingredients, nothing fancy, remember the regulars' names. The PBLT swaps mayo for pimento cheese, turning a standard BLT into something that belongs here. Cuban breakfast stacks ham, pork, pickles, and Swiss with yellow mustard. The Gambino loads Italian meats without apology. Blueberry cheesecake muffins and locally roasted KBREW coffee round it out. Counter service, shopping center location, closes at 2:30 PM. Built for people who want a solid sandwich and don't need theater.",
    "atmosphere": "Bright shopping center storefront with counter ordering and casual seating. Morning crowd grabs breakfast sandwiches and coffee; lunch brings office workers and neighborhood families. Conversational noise level, no music blaring, just the sound of order callouts and register beeps. Joey works the counter, knows the regulars.",
    "special_features": "Locally roasted KBREW coffee, house-made pimento cheese, breakfast all day (until close), blueberry cheesecake muffins",
