    "hours": "{\"monday\": \"11:30-21:00\", \"tuesday\": \"11:30-21:00\", \"wednesday\": \"11:30-21:00\", \"thursday\": \"11:30-21:00\", \"friday\": \"11:30-21:00\", \"saturday\": \"11:30-21:00\", \"sunday\": \"closed\"}",
    "description": "Mediterranean food in Knoxville where the chef actually knows what he's doing. Avi Zenatti cooked for his family in Morocco and Israel before bringing those recipes to Tennessee—not adapted versions, not fusion experiments, the actual food. Handmade falafel arrives crispy-outside-creamy-inside. Hummus masabacha gets made with imported tahini that matters. The shakshuka tastes like someone's grandmother made it, because essentially someone's grandmother did make it, just two generations back. Fresh fish shows up three times weekly for proper Moroccan tagine. The pita ships from Israel and New York because local bakeries don't get it right. Started vegan-only in 2019, now offers meat for those who want it, but the vegan game remains strong—80% of the menu. First Friday seven-course dinners at 6:30 PM show what Zenatti can do when he really opens up.",
    "atmosphere": "Embassy Suites mezzanine with Gay Street balcony views. Feels like eating in someone's well-appointed home if that home happened to be in a hotel. Bright, health-conscious energy without the preachy wellness vibe. Mix of downtown workers on lunch break and couples who know this is the real deal.",
    "special_features": "First Friday seven-course dinners, 80% vegan menu, fresh fish deliveries three times weekly, pita imported from Israel/NYC, family recipes from Morocco and Israel",
