    "hours": "{\"monday\": \"11:30 AM - 9:30 PM\", \"tuesday\": \"11:30 AM - 9:30 PM\", \"wednesday\": \"11:30 AM - 9:30 PM\", \"thursday\": \"11:30 AM - 9:30 PM\", \"friday\": \"11:30 AM - 10:30 PM\", \"saturday\": \"11:30 AM - 10:30 PM\", \"sunday\": \"11:30 AM - 9:30 PM\", \"notes\": \"Extended hours on Friday and Saturday evenings\"}",
    "description": "Chain ramen shop that knows exactly what it is: accessible Japanese comfort food done right. The #1 Tokyo Tonkotsu Shouyu (half a million bowls sold nationwide) delivers creamy pork bone broth, tender chashu, and a proper 7-minute egg—not trying to be Ippudo, just executing the fundamentals without apology. The viral omurice is legitimately worth the hype: fluffy omelet draped over fried rice with curry or demi-glace, the kind of thing that photographs well because it actually tastes good. Eighteen-hour broths mean they're doing the work even if the vibe is more \"fast-casual ramen\" than \"serious bowl.\" West Knoxville location where you can get a solid bowl without driving to a major city.",
    "atmosphere": "Modern chain aesthetic with Instagram-friendly honeycomb booth pods and a literal robot delivering drinks. Two-level dining space with wooden tree installations hung with paper tags like Kyoto temples, but brighter and cleaner than any temple you've visited. Fast-casual energy—order at counter, find your pod, robot brings bubble tea. Families, college kids, first-date couples all coexist comfortably.",
    "special_features": "Honeycomb pod seating, robot drink delivery, viral omurice, 18-hour broths, TBaar bubble tea integration",
