    "hours": null,
    "description": "Nathan Kitner started with a mobile coffee cart before partnering with Southside Garage to open this permanent South Knox storefront on January 2, 2025. Otto Coffee Club local beans, house-made syrups, local baked goods from Knoxville suppliers. The transition from cart to brick-and-mortar added indoor seating and equipment while keeping the carefully curated espresso program and friendly-barista energy that built the following. Workspace-friendly with Wi-Fi and outlets, dog-friendly patio, the kind of neighborhood spot where regulars show up daily and students camp out for hours. Not chasing third-wave trends or Instagram aesthetics—just executing solid coffee shop fundamentals with local sourcing and genuine community focus.",
    "atmosphere": "Bright, graffiti-walled interior with cozy seating and warm lighting. Mix of UT students with laptops, South Knox neighbors catching up, remote workers claiming tables for the afternoon. Dog-friendly patio with potted plants. Feels like a neighborhood living room that happens to serve excellent espresso.",
