    "website": "https://www.instagram.com/motherbarknox/",
    "hours": "{\"monday\": \"Closed\", \"tuesday\": \"16:00-23:00\", \"wednesday\": \"16:00-23:00\", \"thursday\": \"16:00-23:00\", \"friday\": \"16:00-23:00\", \"saturday\": \"16:00-23:00\", \"sunday\": \"Closed\"}",
    "description": "Plant-obsessed wine and cocktail bar from the couple behind Oglewood Avenue Plant Shop. Jade and Dylan Pacifico built this as the social space their plant shop couldn't be—botanicals everywhere, floral cocktails that actually taste good, and a deliberately cozy vibe that went Instagram-viral without trying. The signature lavender lemon martini walks the line between pretty and functional. Small plates trend European tapas: flatbreads, charcuterie, comfort food that pairs with $9-$11 glasses of natural wine. Upstairs gift shop means you can sip-and-shop if that's your thing. Young owners (27 and 28) who know their lane and stay in it.",
    "atmosphere": "Feminine, plant-filled downstairs space that feels like drinking in a greenhouse. Young professional crowd skews date-night and friend-groups. Conversation-friendly volume. The botanical theme is committed—not just a few succulents, but a full garden aesthetic that justifies the Instagram attention. Welcoming without being precious about it.",
    "special_features": "Plant-inspired botanical cocktails, connected to Mother Shop gift store upstairs, European-inspired small plates, natural wine focus, viral Instagram presence",
    "opening_date": "2025-10-04T00:00:00Z",
