    "description": "Unique cafe concept opened August 2023 by owner Shay Gregory in Fourth & Gill neighborhood, combining specialty coffee service with natural wine program. Dual focus creates versatile gathering space serving morning coffee and evening wine.\n\nCoffee program emphasizes creative producers, sustainable practices, and craft collaboration. Natural wine menu features 8 by-the-glass options and 10-15 by-the-bottle selections spanning red, white, rose, orange, and sparkling varietals. Food menu includes vegan and non-vegan grilled cheese on gluten-free bread, plus baked goods from Girls Gotta Eat Good Bakery and Fräuleinwunder Bakery.",
    "atmosphere": "Small second-floor space in Fourth & Gill with modern-cozy design—clean lines, warm wood, natural light from big windows. Mix of locals working on laptops, neighborhood regulars grabbing morning coffee, and wine-curious visitors during evening hours. Background music stays low enough for conversation. The dual identity (coffee by day, wine by night) creates two different crowds in the same room: productive morning energy shifts to relaxed aperitivo vibe later. Owner Shay often behind the counter, creating that community coffee shop warmth without forcing it.",
    "special_features": "coffee by day, wine by night; easy parking across the street",
