    "hours": "Mon Closed, Tue-Thu 4pm-10pm, Fri 4pm-11pm, Sat 12pm-11pm, Sun 12pm-9pm",
    "description": "PostModern Spirits is Knoxville's craft distillery in the Old City, focusing on mindfully crafted spirits from the intersection of artistry and chemistry. Opened in August 2017, the distillery produces unique spirits and operates Methodology, a cocktail lounge serving flight tastings and an ever-changing cocktail menu.\n\nThe distillery specializes in innovative spirits including single barrel and barrel strength rye and straight malt whiskey, whiskey distilled from local craft beer, vodka, multiple gins (including juniper-forward Giniferous and Empirical), and distinctive liqueurs like chamomile, elderberry, cacao, and bitter orange amaro. As a member of the Tennessee Whiskey Trail, PostModern offers guided distillery tours on weekends, showcasing their commitment to craft spirits designed for cocktail culture.",
    "atmosphere": "Historic train depot turned modern distillery with exposed brick and industrial bones. The Methodology cocktail lounge has bright blue patio chairs outside (dog-friendly, smoker-friendly) and a tasting room inside where bartenders who actually know spirits make drinks based on what you like, not what's trending. Mix of cocktail nerds, distillery tourists doing weekend tours, and Old City regulars who want something smarter than a beer bar. Laid-back vibe—people come to learn about gin varieties and chamomile liqueur, not to be seen.",
    "special_features": "Distillery, Tennessee Whiskey Trail",
    "opening_date": "2017-08-01T00:00:00Z",
