    "hours": "Daily: 7:00 AM - 2:00 PM",
    "description": "Knoxville's acclaimed kosher-style bagel shop expands to Cedar Bluff with hand-rolled bagels that critics call \"the best Everything Bagel of my life.\" This sunny bakery produces up to 500 daily bagels in flavors from poppyseed to cheddar jalapeño, all boiled and baked on-site.\n\nThe team behind USA TODAY's 2024-featured downtown Potchke Deli brings their exceptional craft to north Knoxville. Each bagel achieves the perfect balance: crusty, chewy exterior with a fluffy interior. Beyond traditional bagels with schmears, the bakery offers babka loaves, black-and-white cookies, rugelach, and sandwiches built on their signature hand-rolled foundation.",
    "atmosphere": "Bright, bustling bakery where the bagel-rolling table is the show. Packed by 7:45 AM with regulars who know to arrive early. Limited seating around a community table means you watch bagels get hand-rolled, boiled, baked while you eat. The energy is pure morning hustle—no lingering, just exceptional bagels and out.",
    "special_features": "Can produce up to 500 bagels daily; all bagels hand-rolled and boiled on-site; sister location to downtown Potchke Deli featured in USA TODAY 2024",
