    "name": "Primo Passo Coffee Co.",
    "address": "2099 Thunderhead Rd, Ste 103, Knoxville, TN 37922",
    "cuisine_type": "Coffee & Cafe",
    "price_range": "$",
    "phone": "(865) 777-2151",
    "website": "https://www.ppcknox.com",
    "hours": "{\"mon\": \"7am-3pm\", \"tue\": \"7am-3pm\", \"wed\": \"7am-3pm\", \"thu\": \"7am-3pm\", \"fri\": \"7am-3pm\", \"sat\": \"7am-3pm\", \"sun\": \"7am-3pm\"}",
    "description": "Family-owned specialty coffee shop opened in April 2025 by Laura Casner and Andrew Aicklen, self-described \"coffee nerds\" who moved to East Tennessee in 2019. The name \"Primo Passo\" (first step) reflects their mission to provide perfectly brewed coffee in a welcoming environment. Sister location to their LA shop.\n\nSmall-batch coffee roasting program partnering with select roasters for variety and quality. Menu features espresso-based drinks including lattes, cappuccinos, and cortados, plus single-origin pour-overs, drip coffee, teas, and non-caffeinated options. Partners with Potchke for bagels and babkas, plus offers pastries, yogurt parfaits, and grab-and-go breakfast items. Every drink prepared with precision and care.",
    "atmosphere": "Newer specialty coffee shop in a Northshore Town Center strip mall. Bright, clean space with community coffee shop vibe—mix of remote workers on laptops, morning regulars, and curious first-timers. Conversation-friendly volume. Gets busy mid-morning; wait times during peak hours. The focus is the coffee bar where baristas dial in precision espresso drinks and single-origin pour-overs. Shopping center location means functional rather than atmospheric, but the quality of coffee and genuine welcome from owner-operators make it work.",
    "special_features": "Small family-owned specialty coffee shop opening spring 2025 at 2099 Thunderhead Rd Suite 103, with sister location in Santa Monica, CA. Expert baristas with 10 years experience roast in small batches and partner with other specialty roasters to bring variety of quality coffee. Recipes dialed in to extract only the best flavor profiles.",
