    "description": "Set on the woodsy campus of Maryville College in a restored historic estate, RT Lodge offers refined Southern cuisine in an elegant yet relaxed setting. Daily-changing menus showcase seasonal ingredients from local farms and purveyors.\n\nChef Trevor Stockton, trained at renowned Blackberry Farm, crafts elevated Southern dishes that celebrate regional flavors and artisanal techniques. Signature offerings include buttermilk fried chicken with fermented jalapeño hot sauce and housemade charcuterie from the chef's family farm, alongside four-course seasonal tasting menus.",
