    "phone": "(865) 770-5989",
    "website": "https://www.radiusrooftopbar.com/",
    "hours": "Mon-Wed 4-11pm, Thu 4pm-12am, Fri 1pm-1am, Sat 1pm-1am, Sun 4-10pm",
    "description": "Perched on the 14th floor of the Embassy Suites Downtown, Radius delivers Knoxville's most spectacular rooftop experience with wraparound views of the city skyline, Smoky Mountains, and Tennessee River. This sophisticated bourbon bar and lounge opened in 2020.\n\nThe venue showcases Knoxville's finest bourbon selection alongside craft cocktails like The Volunteer with orange vodka and chili-infused honey, and the Southern Smash with whiskey, maple syrup, and fresh mint. Tapas and small plates including charcuterie boards and truffle fries complement the extensive spirit book. Indoor and outdoor seating areas feature a poolside atmosphere and fire pit for year-round entertaining.",
    "atmosphere": "Glass-walled 14th floor lounge with wraparound city and mountain views. Smart casual crowd leans younger on weekends when music turns up and the space goes from sunset cocktails to \"LITTY\" mingling. Fire pit on the outdoor deck, pool area with lounge seating. Sleek modern aesthetic with vaulted ceilings. Mix of tourists hitting the obvious rooftop spot and locals who know the bourbon selection is real.",
