    "description": "Brooklyn-born family tradition meets Knoxville hospitality at this intimate Italian haven. Operating for over 26 years, Savelli's has become a candlelit cornerstone of Sutherland Avenue, specializing in New York-style brick-oven pizza and coastal seafood favorites.\n\nThe kitchen balances traditional Italian techniques with creative coastal influences, crafting Maryland-style crab cakes and Grouper Piccata alongside classic pasta dishes. Hand-tossed pizzas emerge from a gas brick oven with characteristic New York crispness, while an extensive vegetarian menu showcases the kitchen's range. As one of Knoxville's rare BYOB establishments, the intimate dining room encourages guests to pair personal wine selections with chef-driven Italian fare.",
    "atmosphere": "Comfortable casual dining space featuring intimate table arrangements welcoming to families and groups.",
    "special_features": "BYOB wine (cork fee), brick-oven pizza, vegetarian options",
