    "hours": "Mon: Closed, Tue-Sat: 5:00 PM-9:30 PM, Sun: 4:00 PM-9:00 PM",
    "description": "Strip mall sushi on Millertown Pike that earns regulars through fish quality, not Instagram angles. Ricky and Angel run the operation—he lived in Japan, worked sushi in San Francisco, and takes fish seriously. Nothing gets adulterated with food coloring, portions are generous without being wasteful, and presentation stays clean even on to-go orders. The Tennessee roll and signature Kamakaze exist alongside yakitori and hibachi dinners for people who want cooked food. Traditional wagasas hang from the ceiling. Closed Mondays, dinner-only Tuesday through Sunday. Not chasing trends, not apologizing for being in a strip center—just making proper sushi for North Knoxville.",
    "atmosphere": "Calm strip mall Japanese with wagasas on the ceiling. Dad and son behind the sushi bar, daughter working the floor. Traditional decor without trying too hard. Quiet enough for conversation, straightforward about what it is.",
