    "hours": "{\"mon\": \"8am-3pm\", \"tue\": \"8am-3pm\", \"wed\": \"8am-3pm\", \"thu\": \"8am-9pm\", \"fri\": \"8am-9pm\", \"sat\": \"8am-3pm, 4pm-9pm\", \"sun\": \"9am-3pm\"}",
    "description": "Knoxville's only authentic French creperie, opened in 2008 by Allen and Susan Tate after years living in Paris's 7th arrondissement. Imports French wheat and buckwheat flour monthly—the real Breton stuff—for 40+ crepe variations from classic sugar-and-butter to the savory Monte Carlo (ham, Swiss, béchamel on buckwheat). Kitchen learned techniques in Brittany, makes everything to order, serves gluten-free versions that actually work. Sunday French brunch goes all day, weekend beignets appear as sides. The move: Parisian ham and Swiss on buckwheat for savory, Nutella-banana for sweet. Lavazza espresso, full bar with French wines, proper café vibe in downtown Knoxville where European-style cafes don't exist otherwise.",
    "atmosphere": "Vintage French posters on walls, café tables, European soundtrack. Feels like the Latin Quarter transplanted—casual, unstudied, focused on the food rather than performing Frenchness. Mix of downtown workers, couples treating brunch as an event, tourists who stumbled into something real. Conversation-friendly, relaxed service, zero pretense.",
    "special_features": "Crepes, sandwiches, cider, cozy atmosphere",
