    "hours": "{\"mon\": \"11am-3am\", \"tue\": \"11am-3am\", \"wed\": \"11am-3am\", \"thu\": \"11am-3am\", \"fri\": \"11am-3am\", \"sat\": \"11am-3am\", \"sun\": \"11am-3am\"}",
    "description": "Fort Sanders college bar near UT campus that won its reputation on wings and hasn't let go. Multiple local wing competition winner—the Apocalypto and Buffalo Garlic Parm flavors are the trophies. Wings come traditional bone-in or boneless, fresh-cooked to order with lemon pepper or cajun seasoning. Half-pound black angus burgers and pub standards fill out the menu. The specials matter here: 75-cent Wing Wednesday is the move, Taco Tuesday exists, weekend breakfast runs 11 AM to 3 PM. Open until 3 AM daily. This is what it is—college sports bar with legitimately good wings, late hours, and UT game day energy.",
    "atmosphere": "Dive bar vibe with TVs, jukebox, and college crowd. Laid-back during lunch/dinner, louder at night especially on game days. The kind of place that charges cover on busy weekends but serves 75-cent wings on Wednesdays.",
