    "description": "Half fresh seafood market, half casual lunch counter where you point at what you want and they cook it how you want it. The setup is straightforward: glass case full of Gulf shrimp, sushi-grade tuna, salmon, scallops, oysters shipped in daily from three coasts. Pick your fish, choose grilled, fried, or blackened, grab a table. The shrimp po'boy is the move—overstuffed with bite-sized shrimp on a toasted bun, their secret seasoning doing actual work. Broccoli slaw is legitimately the best in Knoxville. Hushpuppies, fried okra, potato salad round out the plate. This isn't fine dining, it's a Farragut strip mall doing one thing well: getting fresh seafood from dock to plate without overthinking it.",
    "atmosphere": "Shopping center seafood counter with fluorescent lighting and a working fish case. Lunch crowds line up to the door, order at the counter, wait for your number. Mix of regulars grabbing takeout and families eating at simple tables. Smells like a Louisiana fish market, sounds like a busy cafeteria.",
