    "description": "Carolina mountain Southern executed at chain-restaurant polish on Market Square. Asheville-founded in 2000, now 26 locations chasing $100M revenue (\"We're right there with Chili's,\" says the CEO). The food succeeds at what it's trying to be: honey-dusted fried chicken with proper crust, shrimp and grits that don't cut corners, biscuits with honey butter worth ordering. Chicken and waffles are the signature move. The bar does hand-crafted cocktails and local craft beers, \"Hoot & Holler Happy Hour\" runs 4-6 PM weekdays. Not grandma's kitchen—corporate Southern with good sourcing and competent technique, delivered in wood-heavy dining rooms designed to evoke southern mansion porches without claiming authenticity.",
    "atmosphere": "Upscale casual chain atmosphere with wood-heavy design evoking southern porch aesthetic. Market Square patio draws brunch crowds and people-watchers. Clean, polished, predictable—the kind of place where you know exactly what you're getting before you sit down.",
    "special_features": "Hoot & Holler Happy Hour Mon-Fri 4-6pm, Brunch served weekends from 9am, Patio seating with Market Square views, House-made biscuits, Responsibly sourced ingredients",
