    "hours": "{\"mon\": \"closed\", \"tue\": \"7am-3pm\", \"wed\": \"7am-3pm\", \"thu\": \"11am-7pm\", \"fri\": \"7am-3pm\", \"sat\": \"7am-3pm\", \"sun\": \"7am-3pm\"}",
    "description": "Interactive coffee lounge where you actually brew your own coffee instead of ordering it. Founder Andrew Ellis hands you 25+ single-dosed vials from roasters across the country, guides you through grinders and pour methods, then steps back while you make it yourself. The point isn't efficiency—it's the opposite. You're here to slow down, grind beans, smell them, choose a brewer, screw up the first pour, dial it in on the second. Cupping classes pair five beans with fruits, chocolates, and nuts to train your palate. The space feels library-quiet: antique typewriters, vintage cameras, blacked-out windows, warm lighting. Not for a quick caffeine hit. For people who want coffee to be an activity, not a transaction.",
    "atmosphere": "Dark, moody room with vintage curios on shelves—typewriters, globes, cameras. Blacked-out windows shut out street noise. Warm lighting, comfortable seating, library-quiet vibe. Feels intentional, contemplative, like stepping into a slower gear.",
    "special_features": "Opened September 2025 at 114 Carr St, first coffee lounge in Knoxville where customers control their own brewing experience. Features 25+ beans from small roasters nationwide with new featured roaster monthly, offers largest selection of coffee beans in country. Dark moody library-like atmosphere with antique typewriters, cameras, globes, plus water filtering system for true coffee tasting. Limited Founders Club for 100 people with exclusive pottery mugs, 52 cups of coffee in first year, and exclusive beans.",
    "opening_date": "2025-08-01T00:00:00Z",
