    "hours": "Sunday-Tuesday: 10am-6pm, Wednesday-Thursday: 10am-7pm, Friday-Saturday: 10am-9pm",
    "description": "Food truck and brick-and-mortar spot run by Henry McGowan, who spent 30+ years cooking before opening this Memphis-style barbecue operation with his grandson. The ribs are what bring people in—slow-smoked until tender, properly seasoned—but the mac and cheese is what makes them regulars. Not \"good for barbecue mac,\" just legitimately great mac and cheese that happens to come with smoked meat on top. Collard greens cooked low and slow, potato salad that doesn't lean sweet, pulled pork and chicken that taste like smoke instead of sauce. Black-owned, family-run, open seven days. This is what soul food barbecue looks like when someone who actually knows how to cook decides to do it right.",
    "atmosphere": "Casual food truck setup with a no-frills approach. Order-at-the-window service, picnic table seating when available. The food is the show—no Instagram moments, just proper smoke and seasoning. Pembroke Avenue location means easy parking and zero pretense.",
    "special_features": "Catering available for events, Memphis-style smoking techniques, 30+ years culinary experience, food truck and brick-and-mortar location",
