    "description": "Family steakhouse since 1968 that survived an arson fire set by a disgruntled employee, temporary relocation to an L&N railroad station, and three ownership handoffs without losing its grip on what made it work: flame-grilled steaks, Woodshed Potatoes (fried potato slices with crispy onions, no breading), and homemade Italian cream cake served warm. The King siblings run it exactly like their parents Bunt and Helen did—house salad, hot bread, broccoli casserole, prime rib on weekends. Southern Living called it legendary, which mostly means it hasn't changed much in 55 years and isn't trying to.",
    "atmosphere": "Rustic log cabin carved into a mountainside with zero pretense. Wood-paneled dining rooms, families celebrating occasions, couples who've been coming since the 1970s. BYOB because there's no liquor license. The kind of place where \"fancy\" means prime rib instead of sirloin.",
